var EXTRA=[{"dot": "gray", "j": "J Knee Surg", "h": "Irrigazione iperosmolare in artroscopia: prova preclinica nel cane", "v": "Studio animale, non sull'uomo: articolarità maggiore con le soluzioni iperosmolari rispetto all'isotonica, per il resto differenze quasi sempre non significative. Nessun dato clinico.", "pmid": "42855160", "doi": "10.1055/a-2976-6929", "temi": ["artroscopia", "irrigazione", "modello animale"]}, {"dot": "gray", "j": "BMC Sports Sci Med Rehabil", "h": "Fatica degli hamstring o del quadricipite: carichi diversi sul LCA nell'atterraggio", "v": "RCT di laboratorio su atleti sani con misure surrogate: la fatica degli hamstring riduce la flessione e aumenta il taglio tibiale anteriore, quella del quadricipite altera i momenti in abduzione. Nessun infortunio misurato.", "pmid": "42829434", "doi": "10.1186/s13102-026-02103-y", "temi": ["LCA", "prevenzione", "atterraggio"]}, {"dot": "gray", "j": "Sports Biomech", "h": "Atterraggi sbilanciati: più abduzione del ginocchio, anche con carico cognitivo", "v": "Studio di laboratorio su adulti attivi: l'abduzione di picco è maggiore quando l'atterraggio è sbilanciato; nessuna interazione con il carico cognitivo. Misura surrogata del rischio di LCA.", "pmid": "42841510", "doi": "10.1080/14763141.2026.2741554", "temi": ["LCA", "rischio di infortunio", "biomeccanica"]}, {"dot": "gray", "j": "Sports Med Open", "h": "Calciatrici dopo LCA: fiducia e sostegno sociale decidono il rientro", "v": "Scoping review: incertezza, paura e scarso sostegno frenano il rientro, fiducia e motivazione lo favoriscono. Pochi studi inclusi, solo percezioni riferite.", "pmid": "42828697", "doi": "10.1186/s40798-026-01118-6", "temi": ["LCA", "rientro allo sport", "fattori psicosociali"]}, {"dot": "gray", "j": "J Arthroplasty", "h": "Sanguinamento dopo TKA: i chirurghi concordano su che cosa lo rende problematico", "v": "Sondaggio strutturato fra chirurghi protesisti con soglia di accordo fissata prima: definizione basata su eventi clinici più che su misure isolate. Opinione di esperti, non dati di pazienti.", "pmid": "42855015", "doi": "10.1016/j.arth.2026.10.001", "temi": ["protesi totale di ginocchio", "emostasi", "consenso di esperti"]}, {"dot": "gray", "j": "Med Eng Phys", "h": "Navigazione con smartphone per i pin di taglio nella TKA: prova su modelli ossei", "v": "Valutazione preclinica su ossa surrogate con tre operatori: deviazioni angolari piccole rispetto al piano. Nessun paziente e nessun confronto con robot o strumentario standard.", "pmid": "42854715", "doi": "10.1088/1873-4030/aeb26c", "temi": ["protesi totale di ginocchio", "navigazione", "studio preclinico"]}, {"dot": "gray", "j": "Eur J Radiol", "h": "TC cone-beam sotto carico nell'artrosi dell'arto inferiore: revisione delle applicazioni", "v": "Revisione: allineamento, rotazione e spazio articolare in un'unica acquisizione sotto carico, con uso nella pianificazione di osteotomie e protesi. Quadro descrittivo, senza confronto di esiti.", "pmid": "42854503", "doi": "10.1016/j.ejrad.2026.113285", "temi": ["TC sotto carico", "allineamento", "osteotomia"]}, {"dot": "gray", "j": "J Athl Train", "h": "Dolore femororotuleo: l'estensione contro resistenza fa più male nell'arco intermedio", "v": "Studio trasversale in laboratorio: quasi tutti hanno dolore in almeno un arco di movimento, più intenso in quello intermedio; la coppia è più bassa negli ultimi gradi di estensione. Nessun esito di trattamento.", "pmid": "42852459", "doi": "10.4085/1062-6050-0046.26", "temi": ["dolore femororotuleo", "quadricipite", "riabilitazione"]}, {"dot": "gray", "j": "Curr Opin Pediatr", "h": "Fratture a manicotto della rotula: il ritardo diagnostico è la causa evitabile principale", "v": "Revisione dell'Hospital for Special Surgery: la diagnosi poggia sull'esame clinico più che sulla radiografia; nessuna fissazione dimostrata superiore, mancano studi comparativi in pediatria.", "pmid": "42853192", "doi": "10.1097/MOP.0000000000001630", "temi": ["rotula", "pediatria", "frattura"]}, {"dot": "gray", "j": "J Arthroplasty", "h": "Sintomi alla caviglia dopo TKA nel ginocchio varo: pesa l'artrosi di caviglia", "v": "Coorte coreana: peggiorano più spesso i pazienti con artrosi di caviglia già presente; gli autori raccomandano la valutazione radiografica della caviglia. Campione piccolo, 12 mesi.", "pmid": "42843683", "doi": "10.1016/j.arth.2026.09.052", "temi": ["protesi totale di ginocchio", "caviglia", "allineamento"]}, {"dot": "gray", "j": "J Arthroplasty", "h": "Presa di posizione AAHKS su sostituti cutanei e medicazioni di collagene in protesi", "v": "Posizione di una società di chirurgia protesica. Su PubMed l'abstract non è disponibile: contenuto non letto e non giudicabile da qui.", "pmid": "42855017", "doi": "10.1016/j.arth.2026.10.004", "temi": ["protesi totale di ginocchio", "presa di posizione", "medicazioni"]}, {"dot": "gray", "j": "J Orthop Case Rep", "h": "Solette con cuneo laterale su misura nell'artrosi mediale: coorte non randomizzata", "v": "Allocazione decisa dal chirurgo, con rischio di selezione dichiarato dagli autori; esiti artrocinematici e di risonanza a sei mesi, risultati intermedi.", "pmid": "42851900", "doi": "10.13107/jocr.2026.v16.i10.8346", "temi": ["artrosi mediale", "solette", "risonanza"]}];
var SCOPERTE=[{"t": "Un menisco artificiale che rilascia farmaci: il problema è farli aderire", "v": "Ingegneria dei biomateriali: rivestimenti a rilascio di desametasone e celecoxib su un impianto meniscale in poliuretano; il lavoro confronta quattro modi di farli aderire e li prova in bioreattore con un modello ovino. Vale la deviazione perché mostra dove si blocca un impianto meniscale oltre la forma: nel legame fra materiale e farmaco. Non ha pazienti.", "pmid": "42853088", "doi": "10.1021/acsami.6c10220", "temi": ["menisco", "biomateriali", "impianto meniscale"]}, {"t": "Dieta chetogenica e artrosi nel topo: che cosa succede al muscolo", "v": "Studio sul topo obeso con menisco destabilizzato, non sull'uomo: la dieta fa perdere peso e abbassa la glicemia senza ridurre la massa del gastrocnemio né peggiorare in modo sostenuto la prestazione motoria, con un muscolo che cambia metabolismo. Vale la deviazione perché chiede che cosa costa dimagrire a un'articolazione che ha bisogno di muscolo.", "pmid": "42854762", "doi": "10.1016/j.jnutbio.2026.110515", "temi": ["dieta", "muscolo", "artrosi"]}, {"t": "Nanoparticelle che lubrificano sotto carico e si ricostituiscono a riposo", "v": "Ingegneria meccanica (Tsinghua, Pechino): nanoparticelle i cui legami si rompono sotto taglio e si riformano a riposo, per lubrificare e rilasciare farmaco nelle zone infiammate, provate su modelli di artrosi del ginocchio e della mandibola. Vale la deviazione perché tratta la lubrificazione come un problema di meccanica prima che di biologia; l'abstract non riporta dati umani.", "pmid": "42852492", "doi": "10.1002/adma.75311", "temi": ["lubrificazione", "tribologia", "artrosi"]}];
var SOC={"1": {"video": "Dopo il crociato un muscolo può aver recuperato forza e restare più cedevole. Lo mostra una revisione di sei studi con l'elastografia, un'ecografia che misura la rigidità del muscolo.\n\nSu 173 persone operate e 79 controlli, il vasto mediale, sulla parte interna della coscia, era meno rigido nella gamba operata, e questo si legava a forza, funzione e modo di atterrare. Dopo il prelievo di un tendine posteriore della coscia, anche il semitendinoso era meno rigido.\n\nIl limite: pochi studi di qualità non sempre buona, nessun dato su chi si fa male di nuovo o torna allo sport. Per ora la misura non guida la riabilitazione.\nFonte: PubMed, PMID 42815174.", "linkedin": "Elastografia dopo LCA: vasto mediale più cedevole nell'arto operato (g di Hedges da -1,10 a -1,21 contro i controlli), revisione sistematica di 6 studi (Marczak, Jaffri e coll., Clin Biomech, settembre 2026).\n\n173 operati e 79 controlli: il deficit si associa a forza del quadricipite, funzione e atterraggio; il semitendinoso è meno rigido dopo il prelievo del tendine (g da -1,29 a -1,64), non a metà ventre dopo il rientro allo sport.\n\nLimiti: qualità da scarsa a buona, intervalli dei g non riportati nell'abstract, nessun esito di re-rottura o di rientro.\nFonte: PubMed, PMID 42815174.", "instagram": "La forza dopo il crociato dice tutto del muscolo?\nIn una revisione di 6 studi il vasto mediale della gamba operata era meno rigido, in relazione a forza e modo di atterrare.\nSono pochi studi, nessun dato su nuove rotture.\nFonte: PubMed, PMID 42815174.", "pazienti": "Dopo l'operazione al legamento crociato, guardare solo la forza non basta a capire come sta il muscolo.\n\nIn una revisione di 6 studi, un muscolo della coscia, il vasto mediale, era meno rigido nella gamba operata, in relazione a forza, funzione e modo di atterrare. La misura si fa con un'ecografia speciale.\n\nSono pochi studi e non dicono nulla su chi si fa male di nuovo: la riabilitazione si decide con il chirurgo e il fisioterapista.\nFonte: PubMed, PMID 42815174."}};
var SOCV={"1": {"video": {"chir": ["Elastografia dopo LCA: il vasto mediale operato resta più cedevole dei controlli, g di Hedges da -1,10 a -1,21. Revisione sistematica, Marczak, Jaffri e coll., Clinical Biomechanics, settembre 2026.", "Sei studi, 173 operati e 79 controlli. Il deficit si associa a forza del quadricipite, funzione e biomeccanica dell'atterraggio. Il semitendinoso è meno rigido dopo il prelievo del tendine, g da -1,29 a -1,64, ma non a metà ventre dopo il rientro allo sport.", "Il limite: qualità da scarsa a buona, intervalli di confidenza dei g non riportati nell'abstract, nessun esito di re-rottura né di rientro. La SWE non guida ancora la riabilitazione.\nFonte: PubMed, PMID 42815174."], "misto": ["Dopo il crociato un muscolo può aver recuperato forza e restare più cedevole. Lo mostra una revisione di sei studi con l'elastografia, un'ecografia che misura la rigidità del muscolo.", "Su 173 persone operate e 79 controlli, il vasto mediale, sulla parte interna della coscia, era meno rigido nella gamba operata, e questo si legava a forza, funzione e modo di atterrare. Dopo il prelievo di un tendine posteriore della coscia, anche il semitendinoso era meno rigido.", "Il limite: pochi studi di qualità non sempre buona, nessun dato su chi si fa male di nuovo o torna allo sport. Per ora la misura non guida la riabilitazione.\nFonte: PubMed, PMID 42815174."], "pazienti": ["Dopo l'operazione al legamento crociato, la forza non racconta tutta la storia del muscolo.", "In una revisione di sei studi, un muscolo della coscia, il vasto mediale, era meno rigido nella gamba operata, e questo si legava a forza, funzione e modo di atterrare dopo un salto. La misura si fa con un'ecografia speciale.", "Sono pochi studi e non dicono nulla su chi si fa male di nuovo: la riabilitazione si decide con il chirurgo e il fisioterapista.\nFonte: PubMed, PMID 42815174."]}, "linkedin": {"chir": ["Elastografia dopo LCA: vasto mediale più cedevole nell'arto operato (g di Hedges da -1,10 a -1,21 contro i controlli), revisione sistematica di 6 studi (Marczak, Jaffri e coll., Clin Biomech, settembre 2026).", "173 operati e 79 controlli: il deficit si associa a forza del quadricipite, funzione e atterraggio; semitendinoso meno rigido dopo il prelievo (g da -1,29 a -1,64), non a metà ventre dopo il rientro allo sport.", "Limiti: qualità da scarsa a buona, intervalli dei g non riportati nell'abstract, nessun esito di re-rottura o di rientro, nessuna indicazione clinica della SWE.\nFonte: PubMed, PMID 42815174."], "misto": ["Dopo il crociato, forza e rigidità del muscolo non coincidono: lo mostra una revisione di 6 studi con l'elastografia (Clin Biomech, settembre 2026).", "Su 173 operati e 79 controlli il vasto mediale era meno rigido nella gamba operata, in relazione a forza, funzione e modo di atterrare.", "Limiti: pochi studi, qualità non sempre buona, nessun dato su nuove rotture o rientro allo sport.\nFonte: PubMed, PMID 42815174."], "pazienti": ["Dopo il crociato, la forza non è l'unica cosa da osservare nel muscolo.", "In una revisione di 6 studi, il vasto mediale della gamba operata era meno rigido, in relazione a forza e modo di atterrare.", "Sono pochi studi: il percorso si decide con il chirurgo e il fisioterapista.\nFonte: PubMed, PMID 42815174."]}, "instagram": {"chir": ["LCA: vasto mediale operato più cedevole all'elastografia, g da -1,10 a -1,21.", "Revisione di 6 studi, 173 operati e 79 controlli; semitendinoso meno rigido dopo prelievo, g da -1,29 a -1,64.", "Limiti: IC dei g non riportati, nessun esito di rientro.\nFonte: PubMed, PMID 42815174."], "misto": ["Dopo il crociato la forza non dice tutto del muscolo.", "In 6 studi il vasto mediale operato era meno rigido, in relazione a forza e atterraggio.", "Pochi studi, nessun dato su nuove rotture.\nFonte: PubMed, PMID 42815174."], "pazienti": ["Dopo il crociato guardare solo la forza non basta?", "In 6 studi un muscolo della coscia operata era meno rigido, legato a forza e modo di atterrare.", "Sono pochi studi: se ne parla con il chirurgo.\nFonte: PubMed, PMID 42815174."]}, "reel": {"chir": ["Elastografia dopo LCA.", "Vasto mediale più cedevole, g da -1,10 a -1,21.", "Revisione di 6 studi, IC non riportati.\nFonte: PubMed, PMID 42815174."], "misto": ["Forza e rigidità del muscolo.", "Dopo il crociato non coincidono.", "6 studi, nessun dato su nuove rotture.\nFonte: PubMed, PMID 42815174."], "pazienti": ["Dopo il crociato.", "La forza non dice tutto del muscolo.", "Pochi studi: se ne parla con il chirurgo.\nFonte: PubMed, PMID 42815174."]}}};
var TAGS={"1": {"linkedin": "#Ortopedia #LegamentoCrociato #MedicinaDelloSport", "instagram": "#ortopedia #ginocchio #legamentocrociato #riabilitazione #quadricipite #elastografia #medicinadellosport #chirurgiaortopedica #fisioterapia #ortopediaticino #medicinabasatasulleprove", "kw": "legamento crociato anteriore, riabilitazione, muscolo quadricipite, elastografia"}};
var NLB={"1": {"prof": ["Dopo il LCA l'elastografia vede un vasto mediale più cedevole, anche con la forza recuperata", "Revisione sistematica (Clin Biomech, settembre 2026) di 6 studi, 173 operati di LCA e 79 controlli: il modulo di taglio passivo del vasto mediale è ridotto nell'arto operato (g di Hedges da -1,10 a -1,21 contro i controlli) e si associa a forza del quadricipite, funzione e biomeccanica dell'atterraggio. Il semitendinoso è meno rigido dopo il prelievo del tendine (g da -1,29 a -1,64), non più a metà ventre dopo il rientro allo sport.", "Nota critica: sei studi di qualità da scarsa a buona, intervalli di confidenza dei g non riportati nell'abstract, nessun esito di re-rottura o di rientro, nessun uso della SWE per decidere la riabilitazione."], "mix": ["Dopo il crociato un muscolo può essere forte e restare più cedevole: lo mostra l'elastografia", "Una revisione di 6 studi su 173 persone operate di legamento crociato e 79 controlli ha trovato che il muscolo vasto mediale, sulla parte interna della coscia, è meno rigido nella gamba operata, e che questo si lega alla forza, alla funzione del ginocchio e al modo di atterrare. Dopo il prelievo di un tendine dei muscoli posteriori della coscia, anche il semitendinoso risultava meno rigido.", "Nota sul limite: sono pochi studi di qualità non sempre buona, i valori non hanno intervalli di confidenza nel riassunto, e nessuno ha seguito chi si rompe di nuovo o torna a fare sport."], "paz": ["Dopo l'operazione al crociato, la forza non racconta tutta la storia del muscolo", "In una revisione di 6 studi, dopo l'operazione al legamento crociato un muscolo della coscia, il vasto mediale, risultava meno rigido nella gamba operata rispetto a quella sana o a persone senza lesione. Questo si legava a una minore forza e a un atterraggio diverso nei salti. È una misura fatta con un'ecografia speciale, non ancora usata per decidere la riabilitazione.", "Sono pochi studi e non dicono nulla su chi si fa male di nuovo: il percorso di riabilitazione si decide con il chirurgo e il fisioterapista."], "kw": "legamento crociato anteriore, riabilitazione, muscolo quadricipite, ecografia elastografia"}, "2": {"prof": ["IPACK e blocco tibiale selettivo dopo LCA: morfina a 24 ore e forza a 8 mesi comparabili", "RCT triplo cieco (Anaesthesia, ottobre 2026), 80 ricostruzioni del LCA in anestesia generale con blocco nel triangolo femorale: morfina endovenosa cumulativa a 24 ore, mediana 12 mg (IQR 6-20) con IPACK contro 16 mg (IQR 10-30) con blocco tibiale, p=0,073; nessuna differenza in dolore, forza del quadricipite e single-hop a 4 e 8 mesi.", "Nota critica: p=0,073 su 80 pazienti non è prova di equivalenza, l'intervallo della differenza non è riportato, innesto e procedure associate non sono riportati, esiti fino a 8 mesi e non rotture."], "mix": ["Dopo il crociato due blocchi nervosi hanno dato un controllo del dolore simile", "In 80 persone operate di legamento crociato in anestesia generale, due tipi di blocco nervoso per il dolore dietro il ginocchio hanno portato a un consumo di morfina simile nelle prime 24 ore (12 mg contro 16 mg di mediana). Anche dolore, forza della coscia e salto a 4 e 8 mesi non differivano in modo significativo, e non sono state riportate complicanze.", "Nota sul limite: con 80 persone non si può dire che i due metodi siano davvero uguali, e il riassunto non indica il tipo di innesto."], "paz": ["Dopo il crociato, due modi di calmare il dolore dietro il ginocchio sono risultati simili", "Uno studio svizzero su 80 persone operate al legamento crociato ha confrontato due iniezioni di anestetico vicino ai nervi del ginocchio. Il bisogno di morfina nelle prime 24 ore è stato simile, e anche dolore e forza a 4 e 8 mesi non erano diversi in modo misurabile. Non sono state riportate complicanze.", "Lo studio è di un solo ospedale: la scelta dell'anestesia si decide con l'anestesista."], "kw": "legamento crociato anteriore, dolore dopo l'operazione, blocco nervoso, anestesia al ginocchio"}, "3": {"prof": ["Protesi non cementata contro cementata: media uguale, meno risultati scadenti a 24 mesi", "Studio prospettico (Arch Orthop Trauma Surg, ottobre 2026), 109 TKA primarie, 54 non cementate in titanio stampato in 3D e 55 cementate: FJS-12 medio senza differenza (β=7,4; IC 95% da -1,8 a 16,6; p=0,115), ma PASS raggiunta dal 96,3% contro il 76,4% (differenza 19,9%; IC 95% 7,1-32,9; NNT 5). Nessuna revisione in 24 mesi.", "Nota critica: coorti non randomizzate e diverse per età e sesso, intervallo della media che non esclude una differenza oltre la MCID, un solo design di impianto, sopravvivenza a lungo termine non valutabile."], "mix": ["Protesi di ginocchio con o senza cemento: stessa media, meno persone deluse senza cemento", "In 109 protesi di ginocchio seguite per 24 mesi, il punteggio medio di quanto il ginocchio venga «dimenticato» non differiva fra protesi fissata con cemento e protesi senza cemento dello stesso modello. Però una quota maggiore del gruppo senza cemento ha raggiunto un livello di soddisfazione accettabile (96,3% contro 76,4%). Nessuna protesi è stata rimossa o si è mobilizzata.", "Nota sul limite: i gruppi non erano formati per sorteggio e differivano per età e sesso, ed è un solo modello di protesi; 24 mesi non dicono come vanno le protesi dopo molti anni."], "paz": ["Protesi di ginocchio con o senza cemento: dopo due anni risultati medi simili", "In uno studio su 109 persone con protesi totale di ginocchio, dopo due anni il punteggio medio di quanto il ginocchio venga «dimenticato» era simile con e senza cemento. Nel gruppo senza cemento una quota maggiore di persone ha raggiunto un livello di soddisfazione accettabile. Nessuna protesi ha dovuto essere sostituita.", "I gruppi non erano formati per sorteggio e due anni sono un tempo breve: la scelta del tipo di protesi si decide con il chirurgo."], "kw": "protesi totale di ginocchio, protesi con cemento, protesi senza cemento, soddisfazione dopo la protesi"}, "4": {"prof": ["A 6 mesi dal LCA la prontezza psicologica dipende da ansia e cinesiofobia più che dalla forza", "Studio trasversale (J Athl Train, ottobre 2026) su 58 operati di LCA, regressione gerarchica sull'ACL-RSI: ansia generalizzata +18,1% di varianza, TSK-11 22,3%, KOOS qualità di vita 9,8%, KOOS-Sport 5,3%; dolore, sintomi e misure oggettive aggiungono poco; modello completo 70,5% della varianza (0,64 aggiustato; 0,61 in validazione incrociata).", "Nota critica: 58 pazienti con molti predittori, validazione solo interna, intervalli non riportati, nessun esito di rientro."], "mix": ["Sei mesi dopo il crociato la paura pesa più della forza nel sentirsi pronti allo sport", "In 58 persone operate di legamento crociato, a circa 6 mesi il sentirsi pronte a riprendere lo sport si spiegava soprattutto con ansia generale e paura del movimento, poi con qualità di vita e funzione percepita nello sport. Forza del quadricipite e capacità di saltare, misurate in modo oggettivo, aggiungevano poco.", "Nota sul limite: sono pochi pazienti, misurati una sola volta, e lo studio non dice se chi si sentiva meno pronto sia poi tornato meno allo sport."], "paz": ["Dopo il crociato, sentirsi pronti a tornare allo sport dipende molto da paura e fiducia", "In uno studio su 58 persone operate al legamento crociato, dopo circa 6 mesi il sentirsi pronte a riprendere lo sport era legato soprattutto all'ansia e alla paura di muoversi, più che alla forza misurata. Anche la paura fa parte della ripresa.", "Sono pochi pazienti e una sola misura: il momento di tornare allo sport si decide con il chirurgo e il fisioterapista."], "kw": "legamento crociato anteriore, ritorno allo sport, paura di muoversi, riabilitazione"}, "5": {"prof": ["Machine learning sul LCA: LSI di estensione, KOOS e IKDC separano operati da sani", "Studio di sviluppo e validazione (J Orthop Res, ottobre 2026), 863 partecipanti (659 operati, 204 controlli) e validazione esterna su 174: XGBoost con AUC 0,98 nel test interno e 0,83 in quella esterna, accuratezza 0,95 e 0,82; variabili più informative KOOS qualità di vita, LSI della coppia di estensione a 90°/s, IKDC.", "Nota critica: il compito è distinguere operati da sani, non prevedere rientro o re-rottura; il calo da 0,98 a 0,83 mostra la perdita fuori dal centro di addestramento; intervalli non riportati."], "mix": ["Un modello informatico riconosce un operato di crociato da poche misure di forza e punteggio", "Un modello di apprendimento automatico, addestrato su 863 persone e provato su altre 174 di un altro centro, ha distinto operati di legamento crociato da persone sane usando soprattutto un punteggio di qualità di vita, la forza di estensione del ginocchio e un punteggio di funzione. Fuori dal centro in cui è stato addestrato, la capacità di distinguere è calata.", "Nota sul limite: il modello distingue operati da sani, non dice chi tornerà allo sport o si romperà di nuovo."], "paz": ["Un programma al computer riconosce chi è stato operato di crociato da poche misure", "Un programma di apprendimento automatico, usando punteggi di funzione e di qualità di vita e una misura di forza, ha distinto le persone operate al legamento crociato da quelle sane. Ha funzionato meglio sulle persone del centro in cui è stato sviluppato che su quelle di un altro centro.", "Non dice chi guarirà meglio né quando tornare allo sport: queste decisioni si prendono con il chirurgo e il fisioterapista."], "kw": "legamento crociato anteriore, intelligenza artificiale, recupero dopo il crociato, test di forza"}, "6": {"prof": ["Rottura del quadricipite: ogni punto di fragilità, +1,26 giorni di degenza e -4,32 di Lysholm", "Coorte retrospettiva multicentrica (Ulus Travma Acil Cerrahi Derg, ottobre 2026), 67 operati per rottura acuta: ogni punto di mFI-5 +1,26 giorni di degenza (IC 95% 0,61-1,90); ogni punto di CFS -4,32 punti di Lysholm (IC 95% da -6,98 a -1,67); Lysholm medio 52,2 ± 17,5 a 25,5 mesi; complicanze 10,4% (7 eventi), senza associazione dimostrata.", "Nota critica: retrospettivo, CFS assegnata a posteriori, R² aggiustato 0,163-0,337, analisi delle complicanze sottopotenziata, tecnica non analizzata."], "mix": ["Rottura del tendine quadricipitale: più fragilità, ricovero più lungo e punteggi più bassi", "In 67 persone operate per rottura recente del tendine del quadricipite, chi era più fragile prima dell'intervento è rimasto in ospedale più a lungo (circa 1,3 giorni in più per ogni punto della scala) e dopo oltre due anni aveva un punteggio di funzione più basso (4,3 punti di Lysholm in meno per ogni punto della scala di fragilità). Le complicanze erano 7 su 67, troppo poche per dire se la fragilità le influenzi.", "Nota sul limite: studio retrospettivo, la fragilità è stata valutata a posteriori e il legame non è una dimostrazione di causa."], "paz": ["Rottura del tendine del quadricipite: la fragilità prima dell'intervento conta per il recupero", "In uno studio su 67 persone operate per una rottura recente del tendine che stende il ginocchio, chi era più fragile prima dell'operazione è rimasto più a lungo in ospedale e dopo oltre due anni aveva un punteggio di funzione più basso. Il risultato aiuta a pianificare ricovero e riabilitazione.", "Lo studio guarda indietro nel tempo e non dimostra la causa: il percorso si decide con il chirurgo."], "kw": "rottura del tendine quadricipitale, ginocchio, recupero dopo l'operazione, fragilità"}, "7": {"prof": ["Lesione meniscale degenerativa: in un RCT piccolo il GFC supera il PRP su VAS a 9 mesi", "RCT a tre bracci (J Orthop Case Rep, ottobre 2026), 54 pazienti con K-L I-II e lesione meniscale degenerativa, 18 per braccio: VAS a 9 mesi da 6,21 ± 0,71 a 3,58 ± 0,74 con GFC, da 6,33 ± 0,69 a 5,11 ± 0,77 con PRP, +17,67% con fisiologica (p<0,0001); WORMS -42,25% e -40,22% contro -2,25%, senza differenza fra GFC e PRP.", "Nota critica: 18 per braccio, cecità non descritta, WORMS punteggio d'organo non specifico per il menisco, composizione dei prodotti non riportata, nessun confronto con fisioterapia."], "mix": ["Menisco usurato: in un piccolo studio i fattori di crescita hanno ridotto il dolore", "In 54 persone con artrosi iniziale e una lesione degenerativa del menisco, due infiltrazioni a distanza di un mese con un concentrato di fattori di crescita hanno ridotto il punteggio del dolore (VAS) da 6,2 a 3,6 a 9 mesi; con il plasma ricco di piastrine da 6,3 a 5,1; con la soluzione fisiologica il dolore è peggiorato.", "Nota sul limite: 18 persone per gruppo, non è descritto se i pazienti sapessero quale trattamento ricevevano, e i punteggi della risonanza non dicono se il menisco sia guarito."], "paz": ["Menisco usurato: uno studio piccolo su due tipi di infiltrazione", "In uno studio su 54 persone con un menisco usurato e artrosi iniziale, due infiltrazioni a distanza di un mese di un concentrato di fattori di crescita hanno ridotto il dolore a 9 mesi più del plasma ricco di piastrine; con la soluzione fisiologica il dolore è aumentato.", "Sono pochi pazienti e lo studio ha dei limiti: se un'infiltrazione sia adatta si valuta con il chirurgo."], "kw": "menisco degenerativo, infiltrazione, plasma ricco di piastrine, artrosi iniziale"}, "8": {"prof": ["RM contro artroscopia nei traumi del ginocchio: accuratezza 82,9% per il menisco mediale", "Studio retrospettivo di accuratezza (J Orthop Case Rep, ottobre 2026), 35 pazienti operati in artroscopia: sensibilità della RM da 76,0% a 100,0%, specificità 100,0%; accuratezza 82,9% per il menisco mediale (IC di Wilson 95% circa 67-92%, calcolo mio), kappa 0,768 per il LCA e 0,644 per il menisco mediale.", "Nota critica: solo pazienti poi operati (bias di verifica), 35 casi e 3 LCP, lettori e apparecchio non descritti, un solo centro."], "mix": ["Risonanza e artroscopia nei traumi: il menisco interno è la lesione che sfugge più spesso", "In 35 persone operate in artroscopia dopo un trauma, la risonanza ha riconosciuto bene le lesioni dei legamenti e della cartilagine, ma il menisco interno è stato quello con l'accuratezza più bassa (82,9%). Una risonanza negativa non esclude sempre un danno al menisco quando i sintomi lo fanno sospettare.", "Nota sul limite: sono state esaminate solo persone poi operate e sono pochi casi di un solo centro."], "paz": ["Risonanza e artroscopia dopo un trauma al ginocchio: in genere concordano, con un'eccezione", "In uno studio su 35 persone operate in artroscopia dopo un trauma, la risonanza ha mostrato in genere gli stessi danni visti durante l'intervento. Il menisco interno è stato quello più difficile da vedere: una risonanza senza lesioni non esclude sempre un problema, se i sintomi persistono.", "Sono pochi casi di un solo centro: l'esame si interpreta con il chirurgo."], "kw": "risonanza magnetica ginocchio, menisco, trauma del ginocchio, artroscopia"}};
var ARTICLES=[{n:1,mono:"m-gray",dot:"orange",sec:"res",j:"Clin Biomech",h:"Elastografia dopo LCA: il vasto mediale operato resta più cedevole",v:"Revisione sistematica PRISMA di 6 studi (173 operati di LCA, 79 controlli; qualità da scarsa a buona): il modulo di taglio passivo del vasto mediale è ridotto nell'arto operato (g di Hedges da -1,10 a -1,21 contro i controlli) e si associa a forza del quadricipite, funzione del ginocchio e biomeccanica dell'atterraggio. Il semitendinoso è meno rigido dopo il prelievo del tendine (g da -1,29 a -1,64), non più a metà ventre dopo il rientro allo sport. Intervalli di confidenza dei g non riportati nell'abstract.",ax:"Marczak, Lightle, Brooks, Kyriazi, Chong, Martinez, Thornton, Grindstaff, Jaffri",date:"set 2026",meta:"revisione sistematica, 6 studi, 173 operati e 79 controlli, elastografia a onde di taglio · [SR di studi osservazionali]",pmid:'42815174',doi:'10.1016/j.clinbiomech.2026.106982',journal:"Clinical biomechanics (Bristol, Avon)",authors:"Marczak J, Lightle C, Brooks A, Kyriazi M, Chong W, Martinez J, Thornton G, Grindstaff TL, Jaffri A",design:"Revisione sistematica secondo PRISMA 2020 (Creighton University, Omaha, Nebraska): ricerca su Scopus, PubMed, SPORTDiscus e CINAHL fino a novembre 2025; inclusi gli studi che confrontano la rigidità muscolare degli arti inferiori misurata con elastografia a onde di taglio (SWE) dopo ricostruzione del LCA con l'arto controlaterale o con controlli; selezione ed estrazione da due revisori indipendenti, qualità con la scala di Downs e Black; sintesi narrativa, con g di Hedges (IC 95%) dove i dati lo permettevano. Una stima aggregata non è dichiarata nell'abstract. Lavoro non open access su PMC: contenuto dall'abstract.",pop:"6 studi; 173 partecipanti operati di LCA e 79 controlli; qualità metodologica da scarsa a buona. Tipo di innesto (oltre al prelievo degli hamstring, citato per il semitendinoso), tempo dall'intervento nei singoli studi, età, sesso e protocollo di misura non riportati nell'abstract.",results:"Vasto mediale: modulo di taglio passivo ridotto in modo costante nell'arto operato (g da -1,10 a -1,21 contro i controlli), associato a forza del quadricipite, funzione del ginocchio e biomeccanica dell'atterraggio. Semitendinoso: rigidità ridotta dopo il prelievo del tendine (g da -1,29 a -1,64), ma non a metà ventre dopo il rientro allo sport. I deficit longitudinali persistevano a tre mesi; i risultati in contrazione attiva erano discordi. Nessuno studio ha campionato il vasto mediale obliquo distale né la regione muscolo-tendinea distale degli hamstring. Intervalli di confidenza dei g non riportati nell'abstract.",concl:"Gli autori: la SWE rileva deficit meccanici muscolo-specifici che riguardano la funzione oltre la forza; un vasto mediale cedevole offre una spiegazione meccanica per il paziente forte che atterra rigido, e la ridotta rigidità del semitendinoso segna la morbilità del sito donatore. Servono protocolli standardizzati che campionino le regioni rilevanti e seguano i pazienti fino al rientro allo sport prima che la SWE possa guidare la riabilitazione.",limits:"Sei studi di qualità da scarsa a buona, con pochi partecipanti per muscolo · confronto con controlli o arto controlaterale, non follow-up con esiti duri · nessun dato su re-rotture né sul rientro allo sport · effetti riportati come g senza intervalli nell'abstract, eterogeneità non quantificabile da qui · tipo di innesto non descritto per studio · testo completo non letto.",perte:"Il tuo innesto è il quadricipitale o il retto femorale, quindi il dato sul semitendinoso riguarda chi preleva gli hamstring, non te. Per te conta il vasto mediale: fa parte dello stesso apparato estensore da cui prelevi, e dice che «forza recuperata» e «muscolo che funziona» non sono la stessa cosa. Tocca T4 solo di lato: aggiunge un indicatore meccanico che non è l'LSI, ma nessuno studio incluso lo usa per decidere il rientro e la SWE non è disponibile in ambulatorio. Nessuna azione clinica ne discende oggi."},{n:2,mono:"m-gray",dot:"green",sec:"res",j:"Anaesthesia",h:"Dopo LCA, IPACK e blocco tibiale selettivo analgesizzano allo stesso modo",v:"RCT triplo cieco a Losanna su 80 ricostruzioni del LCA in anestesia generale con blocco nel triangolo femorale: morfina endovenosa cumulativa a 24 ore, mediana 12 mg (IQR 6-20) con IPACK contro 16 mg (IQR 10-30) con blocco tibiale selettivo, p=0,073. Nessuna differenza negli esiti secondari di dolore e funzione, compresi forza del quadricipite e single-hop a 4 e 8 mesi; nessuna complicanza. Intervallo di confidenza della differenza non riportato nell'abstract.",ax:"Beun, Martin, Ngo, Rossel, André, Albrecht",date:"ott 2026",meta:"RCT triplo cieco, 80 pazienti, LCA in anestesia generale, morfina a 24 ore · [RCT unico, un solo centro]",pmid:'42838531',doi:'10.1111/anae.70433',journal:"Anaesthesia",authors:"Beun L, Martin R, Ngo THN, Rossel JB, André M, Albrecht E",design:"RCT randomizzato triplo cieco (Dipartimento di Anestesia, Ospedale universitario di Losanna, Svizzera) con ipotesi di superiorità dell'IPACK: 80 pazienti sottoposti a ricostruzione del LCA in anestesia generale con blocco nel triangolo femorale, assegnati a IPACK con 20 ml di ropivacaina 0,2% oppure a blocco selettivo del nervo tibiale con 5 ml di ropivacaina 0,75%; analgesia di base con paracetamolo, ibuprofene e morfina endovenosa in PCA. Esito primario: morfina endovenosa cumulativa a 24 ore. Secondari: dolore a riposo e in movimento a 2, 24 e 48 ore, articolarità, forza del quadricipite e distanza di cammino a 24 e 48 ore, forza concentrica del quadricipite e single-hop test a 4 e 8 mesi. Lavoro non open access su PMC: contenuto dall'abstract.",pop:"80 pazienti con ricostruzione del LCA in anestesia generale; età, sesso, tipo di innesto, procedure associate (menisco, LET) e numero per braccio non riportati nell'abstract.",results:"Morfina endovenosa cumulativa a 24 ore: mediana 12 mg (IQR 6-20; range 0-54) con IPACK contro 16 mg (IQR 10-30; range 0-66) con blocco tibiale selettivo, p=0,073. Nessuna differenza significativa negli esiti secondari di dolore e funzione, né nei test funzionali tardivi (forza concentrica del quadricipite e single-hop a 4 e 8 mesi). Nessuna complicanza riportata. Intervallo di confidenza della differenza non riportato nell'abstract.",concl:"Gli autori: IPACK e blocco tibiale selettivo danno un'analgesia comparabile dopo ricostruzione del LCA in anestesia generale con blocco nel triangolo femorale, con un impatto simile sugli esiti funzionali.",limits:"Ipotesi di superiorità non confermata, ma p=0,073 su 80 pazienti non dimostra equivalenza: le mediane differiscono di 4 mg e l'intervallo non è riportato · valido per la combinazione studiata (anestesia generale più blocco nel triangolo femorale più FANS e PCA), non per altri schemi · innesto e procedure associate non riportati · esiti funzionali fino a 8 mesi, non rotture né rientro allo sport · testo completo non letto.",perte:"Un RCT svizzero su un tuo intervento, ma di anestesia: non cambia la tecnica chirurgica né tocca le tensioni aperte. Dice che per il dolore posteriore dopo LCA la scelta fra i due blocchi non ha prodotto una differenza dimostrata nel consumo di morfina né nella forza a 8 mesi; è materiale per il dialogo con l'anestesista, a cui spetta la scelta."},{n:3,mono:"m-gray",dot:"green",sec:"res",j:"Arch Orthop Trauma Surg",h:"TKA non cementata contro cementata: stessa media, meno risultati scadenti a 24 mesi",v:"Studio prospettico su 109 TKA primarie (54 non cementate in titanio stampato in 3D, 55 cementate dello stesso design), follow-up completo a 24 mesi: FJS-12 medio non diverso dopo aggiustamento (β=7,4; IC 95% da -1,8 a 16,6; p=0,115), con un intervallo che non esclude una differenza oltre la MCID. Raggiunge la PASS il 96,3% dei non cementati contro il 76,4% (differenza assoluta 19,9%; IC 95% 7,1-32,9; NNT 5). OKS (p=0,91) e tempo alla soddisfazione funzionale senza differenze; nessuna revisione né mobilizzazione.",ax:"De Berardinis, Leggieri, Salari, Polizzotti, Baldini",date:"ott 2026",meta:"coorte prospettica a due bracci, 109 TKA (54 contro 55), FJS-12 a 24 mesi · [III]",pmid:'42853330',doi:'10.1007/s00402-026-06531-w',journal:"Archives of orthopaedic and trauma surgery",authors:"De Berardinis L, Leggieri F, Salari P, Polizzotti G, Baldini A",design:"Studio prospettico a due coorti non randomizzate (livello di evidenza III dichiarato; IRCCS Ospedale San Raffaele, Milano, e Istituto Fiorentino di Cura e Assistenza, Firenze): TKA primarie monolaterali per artrosi terminale, escluse deformità in valgo e interventi bilaterali. Esito primario FJS-12 (Forgotten Joint Score) analizzato sia sulla media (regressione lineare multivariabile, con ponderazione per overlap dei propensity score come analisi di sensibilità) sia lungo la distribuzione (regressione quantilica). Secondari: raggiungimento della PASS (FJS-12 ≥33,3), OKS, tempo alla soddisfazione funzionale. Lavoro non open access su PMC: contenuto dall'abstract.",pop:"109 TKA primarie monolaterali (54 non cementate, 55 cementate), follow-up completo a 24 mesi. Il gruppo non cementato è più giovane (p<0,001) e con più uomini (p=0,008). Età medie, BMI, marca dell'impianto, tecnica di allineamento e uso di robot o navigazione non riportati nell'abstract.",results:"FJS-12 medio senza differenza dopo aggiustamento (β=7,4; IC 95% da -1,8 a 16,6; p=0,115), risultato riprodotto con la ponderazione per overlap; l'intervallo non esclude una differenza superiore alla MCID. Regressione quantilica: i non cementati hanno punteggi più alti al 10° e al 25° percentile (p aggiustato 0,028 e 0,021), non alla mediana né sopra. PASS raggiunta dal 96,3% contro il 76,4% (differenza assoluta 19,9%; IC 95% 7,1-32,9; NNT 5), confermata dopo aggiustamento (p=0,005). OKS p=0,91; tempo alla soddisfazione funzionale p aggiustato 0,39. Nessuna revisione né mobilizzazione.",concl:"Gli autori: la TKA non cementata in titanio stampato in 3D non ha dato un FJS-12 medio significativamente più alto della cementata dello stesso design a 24 mesi, ma ha ridotto in modo significativo la quota di pazienti con consapevolezza articolare scadente.",limits:"Non randomizzato: i gruppi differiscono per età e sesso (aggiustati, non annullati) e il criterio di scelta della fissazione non è descritto nell'abstract · 109 pazienti, intervallo della media largo (da -1,8 a 16,6) · un solo design di impianto · nessuna revisione in 24 mesi non informa sulla sopravvivenza a lungo termine · testo completo non letto.",perte:"Non è detto che sia la tua protesi: l'abstract non nomina marca, robot né navigazione, e l'impianto è in titanio stampato in 3D. Il punto utile è un altro: a media uguale, la coda dei risultati scadenti può essere diversa, e per il colloquio sul «ginocchio dimenticato» conta la quota di pazienti delusi, non solo la media. Non muove nessuna delle tensioni aperte."},{n:4,mono:"m-gray",dot:"green",sec:"res",j:"J Athl Train",h:"A 6 mesi dal LCA la prontezza psicologica dipende da ansia e paura, non dalla forza",v:"Studio trasversale su 58 operati di LCA (età 18,95 ± 5,20 anni; 31 donne), regressione gerarchica sull'ACL-RSI a circa 6 mesi: l'ansia generalizzata aggiunge il 18,1% di varianza, la cinesiofobia (TSK-11) il 22,3%, la qualità di vita del KOOS il 9,8% e il KOOS-Sport il 5,3%; dolore, sintomi e misure oggettive (forza del quadricipite, simmetria dell'hop) aggiungono poco. Modello completo: 70,5% della varianza, valore aggiustato 0,64 e 0,61 in validazione incrociata. Intervalli di confidenza non riportati nell'abstract.",ax:"Murphy, Lyons, Mertz-Bynum, Lugin, Harkey, Kuenze, Baez, Myer, Diekfuss, Petushek",date:"ott 2026",meta:"studio trasversale, 58 operati di LCA a circa 6 mesi, ACL-RSI · [bassa]",pmid:'42852171',doi:'10.4085/1062-6050-0696.25',journal:"Journal of athletic training",authors:"Murphy T, Lyons L, Mertz-Bynum N, Lugin A, Harkey MS, Kuenze C, Baez S, Myer GD, Diekfuss J, Petushek E",design:"Studio trasversale in un laboratorio universitario: 58 partecipanti che avevano completato la riabilitazione standardizzata dopo LCA primario monolaterale e il test di controllo a circa 6 mesi. Prontezza psicologica misurata con ACL-RSI; regressione lineare gerarchica a blocchi ordinati: dati demografici, ansia generalizzata (PROMIS) e cinesiofobia (TSK-11), sottoscale KOOS (dolore, sintomi, qualità di vita, sport), misure oggettive (forza del quadricipite, simmetria dell'hop su un arto). Validazione incrociata interna. Lavoro open access su PMC (PMC13649313), testo completo non letto: numeri dall'abstract.",pop:"58 partecipanti (31 donne, 53%); età 18,95 ± 5,20 anni; circa 6 mesi dopo LCA primario monolaterale. Tipo di innesto, procedure associate, sport praticato e rientro effettivo non riportati nell'abstract.",results:"Dati demografici: 1-4% della varianza dell'ACL-RSI. Ansia generalizzata: +18,1%; cinesiofobia (TSK-11): 22,3%; KOOS qualità di vita: 9,8%; KOOS-Sport: 5,3%. Dolore, sintomi e misure oggettive: contributo piccolo. Modello completo: 70,5% della varianza (valore aggiustato 0,64; 0,61 in validazione incrociata; il simbolo della misura manca nel testo dell'abstract). Intervalli di confidenza e valori di p dei singoli blocchi non riportati nell'abstract.",concl:"Gli autori: convinzioni legate alla paura e funzione percepita hanno un'influenza maggiore sulla prontezza psicologica della simmetria funzionale oggettiva; propongono modelli di valutazione biopsicosociale e misure psicologiche specifiche per lo sport nelle decisioni di rientro.",limits:"Studio trasversale su 58 pazienti con molti predittori: rischio di sovra-adattamento, validazione solo interna · associazioni e non cause · misura la prontezza psicologica a 6 mesi, non il rientro allo sport né le re-rotture · innesto e procedure associate non riportati · nessuna soglia proposta · testo completo non letto.",perte:"Dato laterale per T4: se la prontezza psicologica si spiega con ansia e paura più che con forza e salti, un criterio di rientro fatto solo di LSI non la vede. Non propone soglie né dice che cosa fare con la paura; sposta l'attenzione sul fatto che il rientro ha una dimensione che il test di forza non misura."},{n:5,mono:"m-gray",dot:"gray",sec:"res",j:"J Orthop Res",h:"Apprendimento automatico: poche misure distinguono un operato di LCA da un sano",v:"Modelli addestrati su 863 partecipanti (659 operati di LCA, 204 controlli) e validati su una coorte esterna di 174 (133 operati, 41 controlli): XGBoost con AUC 0,98 (accuratezza 0,95) nel test interno e 0,83 (0,82) nella validazione esterna. Le variabili più informative: sottoscala qualità di vita del KOOS, LSI della coppia di estensione a 90°/s e punteggio IKDC. Intervalli di confidenza non riportati nell'abstract.",ax:"Morrow, Hart, Nelson, Arbeeva, Kelly",date:"ott 2026",meta:"studio di sviluppo e validazione esterna, 863 + 174 partecipanti, classificazione operati contro controlli · [bassa]",pmid:'42845144',doi:'10.1002/jor.70283',journal:"Journal of orthopaedic research : official publication of the Orthopaedic Research Society",authors:"Morrow TA, Hart JM, Nelson AE, Arbeeva L, Kelly DK",design:"Studio di sviluppo e validazione esterna di modelli di apprendimento automatico supervisionato (Random Forest, Gradient Boosting Machine, XGBoost; University of North Carolina at Chapel Hill): 863 partecipanti del primo centro (659 operati di LCA, 204 controlli sani) con divisione 80/20 e validazione incrociata a cinque parti interna; validazione esterna su 174 partecipanti di un secondo centro (133 operati, 41 controlli). Input: valutazioni muscolo-scheletriche degli arti inferiori e PROM; esito: classificare operati contro controlli. Lavoro non open access su PMC: contenuto dall'abstract.",pop:"Centro 1: 863 partecipanti (659 post-LCA, 204 controlli); centro 2: 174 (133 post-LCA, 41 controlli). Tempo dall'intervento, innesto, età e sesso medi non riportati nell'abstract (le variabili più informative sono coerenti tra sottogruppi di età e sesso).",results:"XGBoost, test interno: AUC 0,98, accuratezza 0,95. Validazione esterna: AUC 0,83, accuratezza 0,82. Variabili più informative: KOOS qualità di vita, LSI della coppia di estensione del ginocchio a 90°/s, punteggio IKDC, coerenti tra sottogruppi di età e sesso. Intervalli di confidenza delle AUC non riportati nell'abstract.",concl:"Gli autori: l'apprendimento automatico può integrare forza, funzione e PROM per identificare gli indicatori chiave dello stato post-LCA e sostenere protocolli snelli di monitoraggio e decisioni di rientro; i clinici possono concentrarsi su questi test come batteria ridotta.",limits:"Il compito è distinguere operati da sani, non prevedere chi rientra, chi guarisce o chi si rompe: l'AUC alta non dice nulla su quale soglia usare per un rientro · il calo da 0,98 a 0,83 fuori dal centro di addestramento mostra la perdita di generalizzazione · controlli sani non confrontabili con operati che hanno recuperato · intervalli non riportati · testo completo non letto.",perte:"Poco da portare in ambulatorio: conferma che fra le misure che separano un operato da un sano compaiono LSI di forza, qualità di vita e IKDC, cioè quello che già misuri. Non propone soglie né prevede esiti, quindi non muove T4; sarebbe utile solo se qualcuno lo applicasse alla domanda «chi si ritrova una re-rottura»."},{n:6,mono:"m-gray",dot:"gray",sec:"res",j:"Ulus Travma Acil Cerrahi Derg",h:"Rottura del tendine quadricipitale: la fragilità allunga il ricovero e abbassa il Lysholm",v:"Coorte retrospettiva multicentrica di 67 adulti operati per rottura acuta del tendine quadricipitale (4 centri turchi, 2019-2023; età 57,5 ± 12,1 anni; 79,1% uomini). Ogni punto di mFI-5 = +1,26 giorni di degenza (IC 95% 0,61-1,90; R² aggiustato 0,337); ogni punto di Clinical Frailty Scale = -4,32 punti di Lysholm (IC 95% da -6,98 a -1,67; R² aggiustato 0,163), con Lysholm medio 52,2 ± 17,5 a 25,5 mesi. Nessuna associazione dimostrata con le complicanze (10,4%, 7 eventi): analisi sottopotenziata.",ax:"Ozdemir, Altay, Sen, Akcaalan, Guler, Serpi, Yildirim, Ceylan, Sahbat",date:"ott 2026",meta:"coorte retrospettiva multicentrica, 67 pazienti, fragilità (mFI-5, CFS), degenza e Lysholm · [bassa]",pmid:'42841891',doi:'10.14744/tjtes.2026.36602',journal:"Ulusal travma ve acil cerrahi dergisi = Turkish journal of trauma & emergency surgery : TJTES",authors:"Ozdemir E, Altay N, Sen K, Akcaalan S, Guler Y, Serpi M, Yildirim C, Ceylan H, Sahbat Y",design:"Coorte retrospettiva multicentrica in quattro centri terziari turchi (Erzurum, Ankara, Istanbul): 67 adulti operati di riparazione o ricostruzione per rottura acuta (≤4 settimane) del tendine quadricipitale fra il 2019 e il 2023. Fragilità preoperatoria con il Modified Frailty Index a 5 voci (mFI-5) e la Clinical Frailty Scale a 9 punti (CFS), quest'ultima assegnata retrospettivamente da due chirurghi con consenso a doppia lettura (κ=0,82). Esiti primari: durata della degenza e Lysholm a ≥12 mesi; secondari KOOS e complicanze. Modelli multivariabili ristretti a priori (6 predittori per la degenza, 4 per il Lysholm), aggiustati per età, sesso, BMI, comorbilità, tecnica e follow-up. Lavoro non open access su PMC: contenuto dall'abstract.",pop:"67 adulti; età 57,5 ± 12,1 anni; 79,1% uomini; riparazione o ricostruzione (6 ricostruzioni) per rottura acuta entro 4 settimane; follow-up medio 25,5 mesi. Tecnica di riparazione per paziente, ancoraggi e protocollo riabilitativo non riportati nell'abstract.",results:"Degenza: r=0,404 con mFI-5 (p<0,001); nel modello aggiustato ogni punto di mFI-5 predice +1,26 giorni (IC 95% 0,61-1,90; R² aggiustato 0,337). Lysholm a 25,5 mesi in media 52,2 ± 17,5; la CFS è associata a recupero peggiore (r=-0,328; p=0,007): ogni punto in più corrisponde a -4,32 punti di Lysholm (IC 95% da -6,98 a -1,67; R² aggiustato 0,163). Escludendo le 6 ricostruzioni gli effetti restano simili (β=1,22 per la degenza; β=-4,18 per il Lysholm). Complicanze 10,4% (7 eventi): nessuna associazione significativa, analisi sottopotenziata secondo gli autori.",concl:"Gli autori: la fragilità è associata a degenza più lunga e a esiti riferiti dal paziente peggiori dopo riparazione chirurgica della rottura del tendine quadricipitale; propongono di integrare mFI-5 e CFS nella valutazione preoperatoria per orientare pianificazione, dimissione e intensità riabilitativa.",limits:"Retrospettivo, 67 pazienti, quattro centri e tecniche chirurgiche diverse (6 ricostruzioni) · CFS assegnata a posteriori da due chirurghi · Lysholm a 25,5 mesi senza valore pre-lesione · 7 complicanze: nessuna conclusione sulla sicurezza · associazioni, non cause, con R² aggiustato 0,163-0,337 (gran parte della variabilità resta non spiegata) · testo completo non letto.",perte:"Riguarda il tuo tendine come sede di prelievo, ma non la tua tecnica: è una rottura acuta in pazienti di 57 anni di media, non l'innesto per il LCA. Il dato utile è prognostico: un paziente fragile con rottura acuta ha una degenza più lunga e un Lysholm più basso, da dire nel colloquio. Non muove nessuna delle tensioni aperte."},{n:7,mono:"m-gray",dot:"green",sec:"res",j:"J Orthop Case Rep",h:"Menisco degenerativo: in un piccolo RCT il concentrato di fattori di crescita batte il PRP",v:"RCT a tre bracci su 54 pazienti (18 per braccio; 41-78 anni; artrosi K-L I-II con lesione meniscale degenerativa alla RM): due infiltrazioni a 4 settimane di distanza di PRP, concentrato di fattori di crescita (GFC) o soluzione fisiologica. A 9 mesi la VAS scende da 6,21 ± 0,71 a 3,58 ± 0,74 con GFC, da 6,33 ± 0,69 a 5,11 ± 0,77 con PRP e peggiora del 17,67% con la fisiologica (p<0,0001). Punteggio WORMS: -42,25% (GFC) e -40,22% (PRP) contro -2,25% (p<0,0001), senza differenza fra i due attivi. Intervalli di confidenza non riportati nell'abstract.",ax:"Bishnoi, Jain, Saraf, Awasthi, Rastogi, Kumar",date:"ott 2026",meta:"RCT a 3 bracci, 54 pazienti (18 per braccio), 9 mesi, VAS, WOMAC e WORMS · [RCT piccolo]",pmid:'42851625',doi:'10.13107/jocr.2026.v16.i10.8328',journal:"Journal of orthopaedic case reports",authors:"Bishnoi S, Jain S, Saraf A, Awasthi S, Rastogi R, Kumar SK",design:"RCT a tre bracci paralleli (Bhopal e Moradabad, India): 54 pazienti di 41-78 anni con artrosi sintomatica K-L grado I o II e lesione meniscale degenerativa confermata alla RM, randomizzati a PRP, concentrato di fattori di crescita (GFC) o soluzione fisiologica (18 per braccio), con due iniezioni intra-articolari a 4 settimane di distanza. Esiti: VAS e WOMAC a basale, 1, 3, 6 e 9 mesi; WORMS (whole-organ MRI score) a basale e 9 mesi. Metodo di randomizzazione, occultamento e cecità non riportati nell'abstract. Lavoro open access su PMC (PMC13646794), testo completo non letto: numeri dall'abstract.",pop:"54 pazienti, 18 per braccio, 41-78 anni, K-L I-II con lesione meniscale degenerativa; gruppi comparabili al basale (p>0,05). Preparazione e composizione del PRP e del GFC, sede e tipo della lesione meniscale, sesso e BMI non riportati nell'abstract.",results:"VAS a 9 mesi: GFC da 6,21 ± 0,71 a 3,58 ± 0,74 (-42,35%); PRP da 6,33 ± 0,69 a 5,11 ± 0,77 (-19,27%); fisiologica +17,67% (peggioramento); differenza fra i bracci p<0,0001. WOMAC funzionale: GFC da 59,16 ± 8,26 a 39,97 ± 6,21 (-32,44%); PRP da 59,58 ± 8,72 a 47,33 ± 7,05 (-20,56%); fisiologica +8,53% (p<0,0001). WORMS: GFC -42,25%, PRP -40,22%, fisiologica -2,25% (p<0,0001), senza differenza significativa fra GFC e PRP. Intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: il GFC dà un sollievo del dolore e una funzione superiori al PRP nella malattia meniscale degenerativa precoce, con una stabilizzazione strutturale comparabile alla RM; lo propongono come opzione di preservazione articolare.",limits:"Diciotto pazienti per braccio, un centro, nove mesi · cecità e occultamento dell'allocazione non descritti, con esiti soggettivi (VAS, WOMAC) · il WORMS è un punteggio di organo intero: una sua riduzione del 40% non equivale a guarigione del menisco e l'abstract non dice come o da chi sia stato letto · tipo di lesione meniscale e preparazione dei prodotti non riportati · nessun confronto con fisioterapia o meniscectomia · la conclusione degli autori («potente», «opzione di preservazione articolare») va oltre i dati di un RCT piccolo · testo completo non letto.",perte:"Fuori dalla tua chirurgia: infiltrazioni nella lesione degenerativa con artrosi iniziale. Serve solo come risposta al paziente che chiede dell'infiltrazione per un menisco degenerativo: un piccolo RCT indiano, senza cecità descritta, non una pratica consolidata. Non muove nessuna delle tensioni aperte."},{n:8,mono:"m-gray",dot:"gray",sec:"res",j:"J Orthop Case Rep",h:"RM e artroscopia nei traumi del ginocchio: il menisco mediale sfugge più del resto",v:"Studio retrospettivo di accuratezza diagnostica su 35 pazienti (15-60 anni) con trauma del ginocchio operati in artroscopia terapeutica (31 LCA, 3 LCP, 25 menischi mediali, 14 laterali, 10 difetti osteocondrali): sensibilità della RM da 76,0% a 100,0%, specificità 100,0% per tutte le lesioni; accuratezza 82,9% per il menisco mediale (29 su 35, IC di Wilson 95% circa 67-92%, calcolo mio), 100,0% per LCP e difetti osteocondrali. Kappa 0,768 per il LCA e 0,644 per il menisco mediale.",ax:"Qureshi, Faatima, Agrawal",date:"ott 2026",meta:"studio di accuratezza diagnostica retrospettivo, 35 pazienti, RM contro artroscopia · [bassa]",pmid:'42851563',doi:'10.13107/jocr.2026.v16.i10.8310',journal:"Journal of orthopaedic case reports",authors:"Qureshi A, Faatima N, Agrawal SS",design:"Studio retrospettivo monocentrico di accuratezza diagnostica (Raipur, Chhattisgarh, India): 35 pazienti di 15-60 anni con trauma del ginocchio, valutazione clinica, RM preoperatoria e artroscopia terapeutica; l'artroscopia è lo standard di riferimento. Calcolati sensibilità, specificità, valori predittivi, accuratezza e kappa di Cohen. Selezione dei pazienti, lettori della RM, intensità del campo e cecità rispetto all'artroscopia non riportati nell'abstract. Lavoro open access su PMC (PMC13646553), testo completo non letto: numeri dall'abstract.",pop:"35 pazienti di 15-60 anni; artroscopia: 31 lesioni del LCA, 3 del LCP, 25 del menisco mediale, 14 del laterale, 10 difetti osteocondrali. Tempo fra trauma, RM e artroscopia, tipo di lesione meniscale e apparecchio RM non riportati nell'abstract.",results:"RM contro artroscopia: sensibilità da 76,0% a 100,0%; specificità 100,0% per tutte le lesioni; accuratezza da 82,9% (menisco mediale) a 100,0% (LCP e difetti osteocondrali). Concordanza sostanziale per LCA (κ=0,768) e menisco mediale (κ=0,644), quasi perfetta per LCP (κ=1,000), menisco laterale (κ=0,940) e difetti osteocondrali (κ=1,000). L'accuratezza del menisco mediale, 29 su 35, ha un IC di Wilson 95% di circa 67-92% (calcolo mio). Intervalli di confidenza delle altre misure non riportati nell'abstract.",concl:"Gli autori: la RM ha un'alta resa diagnostica e una concordanza da sostanziale a quasi perfetta con l'artroscopia; per il menisco mediale sensibilità e valore predittivo negativo sono i più bassi, quindi una RM negativa può non escludere una patologia meniscale rilevante se il sospetto clinico resta alto.",limits:"Solo pazienti poi operati in artroscopia: il campione esclude chi ha una RM negativa e non è stato operato, e può gonfiare la specificità (bias di verifica) · 35 pazienti, tre LCP: kappa 1,000 su pochi casi · lettori, apparecchio e cecità non descritti · retrospettivo, un centro · testo completo non letto.",perte:"Conferma ciò che sai dalla pratica: il menisco mediale è la lesione che la RM manca più spesso, e una RM negativa con clinica forte non chiude la questione. Il campione però è selezionato (solo operati), quindi la specificità del 100,0% non va portata ai colleghi come dato generale. Non muove nessuna tensione."}];
var SUGGQ=[{"k": "kol", "n": "Andrea Baldini (Istituto Fiorentino di Cura e Assistenza, Firenze, Italia)", "w": "Italia: ultimo autore dello studio di oggi sulla protesi totale di ginocchio non cementata contro cementata (PMID 42853330; afferenza letta nei metadati PubMed). Corrispondenza tecnica con il versante protesico della tua pratica; l'abstract non nomina marca né robot, quindi la corrispondenza con la VELYS non è verificata. Sostituisce M. L. Nault (10 ottobre, nessun segnale dell'utente arrivato per farla ruotare)."}];
var BRIEF_TEXT="Domenica 11 ottobre. La settimana, in breve: quattro lavori hanno contato. Lunedì uno studio di Göteborg ha mostrato che dopo un crociato con gli hamstring la quota di pazienti sopra il novanta per cento di simmetria va da ottanta a tre per cento a seconda del test usato. Martedì una meta-analisi di nove RCT sull'aumento biologico del crociato non ha dimostrato un vantaggio, senza escluderlo. Venerdì una risonanza a sette tesla ha mostrato che l'estrusione del menisco mediale cresce dopo la sutura della radice anche con suture integre. Sabato la serie della Mayo Clinic sul tendine quadricipitale: forza al settantasette-ottantuno per cento a nove mesi e punteggi buoni a due anni. Le tensioni mosse: il criterio di rientro, toccato tre volte, e la radice meniscale, una volta. Oggi, otto lavori, nessuna scheda rossa e una arancione: nessun richiamo di dispositivi nuovo, nessuna ritrattazione che ti riguardi, nessun nuovo consensus o linea guida nella tua pratica. Il lavoro del giorno, arancione, è una revisione sistematica di sei studi sull'elastografia a onde di taglio dopo il crociato: centosettantatré operati e settantanove controlli. Il vasto mediale della gamba operata è più cedevole che nei controlli, e questo si lega a forza del quadricipite, funzione e modo di atterrare; il semitendinoso è meno rigido dopo il prelievo del tendine. Non riguarda il tuo innesto per il semitendinoso, ma dice che forza recuperata e muscolo che funziona non sono la stessa cosa. Gli intervalli di confidenza non sono riportati nell'abstract e nessuno studio misura le re-rotture. Tra le altre schede: un RCT di Losanna su ottanta crociati trova un consumo di morfina simile con IPACK e con blocco tibiale selettivo, ma un p di zero virgola zero sette tre non dimostra l'equivalenza. Una coorte prospettica di Milano e Firenze su centonove protesi di ginocchio non trova differenze nella media a ventiquattro mesi; la quota che raggiunge una soddisfazione accettabile è però del novantasei per cento senza cemento contro il settantasei con cemento, con gruppi non randomizzati e impianto non nominato. Uno studio trasversale su cinquantotto operati mostra che a sei mesi la prontezza psicologica dipende più da ansia e paura del movimento che dalla forza. Un modello di apprendimento automatico distingue operati da sani con un'AUC di zero virgola ottantatré fuori dal centro di addestramento, ma non prevede il rientro. Completano una coorte retrospettiva sulla rottura del tendine quadricipitale, dove la fragilità si associa a ricovero più lungo e punteggi più bassi, un piccolo RCT su infiltrazioni nel menisco degenerativo con diciotto pazienti per braccio, e uno studio sulla risonanza in cui il menisco mediale è la lesione che sfugge più spesso. Per le proposte da seguire oggi il nome è Andrea Baldini, di Firenze, per la protesi totale di ginocchio.";
var BRIEF_DIALOGO=[{"chi": "A", "t": "Domenica undici ottobre. Prima la settimana: quattro lavori hanno contato, e due tensioni si sono mosse, il criterio di rientro e la radice meniscale."}, {"chi": "B", "t": "Il criterio di rientro è quello della soglia del novanta per cento?"}, {"chi": "A", "t": "Sì. Lunedì un test diverso ha cambiato di molto la quota di pazienti sopra soglia, e sabato la serie della Mayo Clinic sul quadricipite mostrava forza al settantasette-ottantuno per cento con punteggi buoni a due anni."}, {"chi": "B", "t": "E oggi? Otto lavori, nessuna scheda rossa."}, {"chi": "A", "t": "Una arancione: una revisione di sei studi sull'elastografia dopo il crociato. Il vasto mediale operato è più cedevole che nei controlli, e questo si lega a forza, funzione e modo di atterrare."}, {"chi": "B", "t": "Quindi la forza recuperata non basta."}, {"chi": "A", "t": "Esatto: forza recuperata e muscolo che funziona non sono la stessa cosa. Ma gli intervalli non sono riportati e nessuno studio misura le re-rotture."}, {"chi": "B", "t": "E il semitendinoso? Per te non conta, usi il quadricipite."}, {"chi": "A", "t": "Giusto: meno rigido dopo il prelievo del tendine, riguarda chi usa gli hamstring. Altra scheda: l'RCT di Losanna, IPACK contro blocco tibiale dopo il crociato, morfina simile, ma con ottanta pazienti l'equivalenza non è dimostrata."}, {"chi": "B", "t": "E la protesi non cementata?"}, {"chi": "A", "t": "Media uguale a ventiquattro mesi, ma la quota con una soddisfazione accettabile è novantasei per cento senza cemento contro settantasei con cemento. Gruppi non randomizzati, impianto non nominato."}, {"chi": "B", "t": "Quindi per la protesi, conta la coda dei risultati e non solo la media."}, {"chi": "A", "t": "Sì, ed è stato un buon motivo per il nome di oggi, Andrea Baldini di Firenze. Per il resto, poche cose da portare in ambulatorio."}];
